const apiOrigin=location.hostname==='taobuilds.github.io'?'https://lace-pattern-lab-ra.theoshen0928.chatgpt.site':'';
const rosetteIcon='<circle cx="20" cy="20" r="6"/><g>'+Array.from({length:6},(_,i)=>`<ellipse cx="20" cy="8" rx="4" ry="7" transform="rotate(${i*60} 20 20)"/>`).join('')+'</g>';
const motifs={rosette:{label:'Rosette',icon:rosetteIcon},scroll:{label:'Scroll',icon:'<path d="M7 28c18 2 4-22 19-20 11 1 1 17 7 14"/><path d="M10 10c2 8 10 6 12 0"/>'},botanical:{label:'Leaf vine',icon:'<path d="M20 34C7 26 7 11 29 7"/><path d="M18 27C8 27 6 18 8 15c6 0 10 3 10 12M23 18c0-8 6-11 12-10 0 6-4 9-12 10"/>'},diamond:{label:'Openwork',icon:'<path d="M20 3 36 20 20 37 4 20Z M20 10 29 20 20 30 11 20Z"/><path d="M4 20h32M20 3v34"/>'}};
let settings={motif:'rosette',repeat:'halfdrop',ground:'diamond',density:55,weight:3,detail:'balanced',edge:'repeat',surface:'ink',quality:'medium'};let currentImage='ai-lace-study.png',history=[];let sourceImage=null;
const storyMarkup=`<section class="story-module" aria-labelledby="storyTitle"><div class="story-heading"><div><p class="eyebrow">03 / CULTURAL TRANSLATION</p><h3 id="storyTitle">Give the pattern a story.</h3><p>Turn a place, memory or shared idea into a visual rule.</p></div><label class="story-toggle"><input id="storyEnabled" type="checkbox"><span>Use story</span></label></div><div class="story-intro"><p>When a story is enabled, an AI text step first derives a motif, connections, ground and rhythm. That plan then guides the image.</p><button type="button" id="storyExample" class="story-example">Try an editable Cambridge / MIT example ↗</button></div><div id="storyFields" hidden><div class="story-inputs"><div class="story-field"><label for="storyContext">Place or community</label><input id="storyContext" maxlength="100" placeholder="e.g. Cambridge, Massachusetts / MIT"><label for="storySymbols">Images or symbols to reinterpret <span class="optional">optional</span></label><input id="storySymbols" maxlength="180" placeholder="e.g. river current, crossings, shared paths"></div><div class="story-field"><label for="storyNarrative">The story in your own words</label><textarea id="storyNarrative" rows="5" maxlength="700" placeholder="What happened here? What values, memories or tensions should the pattern carry?"></textarea></div><div class="story-field story-options"><label for="storyFocus">Translate through</label><select id="storyFocus"><option value="routes">Paths & connections</option><option value="motifs">Motif hierarchy</option><option value="contrast">Solid & open space</option><option value="rhythm">Repeat & rhythm</option></select><label for="storyAbstraction">Abstraction</label><select id="storyAbstraction"><option value="poetic">Poetic</option><option value="balanced" selected>Balanced</option><option value="recognisable">Recognisable cues</option></select></div></div><div class="story-result"><div class="story-map"><span>STORY → FORM</span><div id="storyMap">The AI translation plan will appear here after you generate.</div></div><p id="storyState" class="story-state">The image above was made before this story. Generate a new one to apply it.</p></div><div class="story-footer"><p class="story-note">The Cambridge example is an invented starting point, not an official MIT symbol. Edit it to reflect your own research.</p><button type="button" id="generateStory" class="pill-button">Generate from this story ↗</button></div></div></section>`;
document.querySelector('.studio-grid').insertAdjacentHTML('afterend',storyMarkup);
const focusRules={routes:'turn movement and encounters into connecting paths and bridges',motifs:'turn places and symbols into a hierarchy of large and small motifs',contrast:'express tensions through solid areas, openings and changing density',rhythm:'express recurring moments through repeat, spacing and edge rhythm'};
const abstractionRules={poetic:'highly abstract, with no literal icons',balanced:'abstract yet traceable to the source story',recognisable:'allow a few recognisable cues while remaining a lace pattern'};
function getStory(){return{enabled:$('#storyEnabled').checked,context:$('#storyContext').value.trim(),narrative:$('#storyNarrative').value.trim(),symbols:$('#storySymbols').value.trim(),focus:$('#storyFocus').value,abstraction:$('#storyAbstraction').value}}
let generatedStory=null,generatedTranslation=null,generatedPrompt=null,generatedSettings=null;
function renderTranslation(plan){if(!plan){$('#storyMap').textContent='The AI translation plan will appear here after you generate.';return}$('#storyMap').innerHTML='';for(const [key,label] of [['sourceCue','Story cue'],['motif','Motif'],['connections','Connections'],['ground','Open ground'],['rhythm','Rhythm'],['meaning','Meaning']]){const row=document.createElement('div');row.className='translation-row';const name=document.createElement('span');name.textContent=label;const value=document.createElement('p');value.textContent=plan[key];row.append(name,value);$('#storyMap').append(row)}}
function storyMatchesImage(){return !!generatedStory&&JSON.stringify(getStory())===JSON.stringify(generatedStory)}
function storyRecipe(){const s=getStory();if(!s.enabled)return'';return `\nCultural source: ${s.context||'[place or community needed]'}.\nNarrative: ${s.narrative||'[story needed]'}.\nSymbols to reinterpret: ${s.symbols||'derive them from the narrative'}.\nTranslation principle: ${focusRules[s.focus]}. Visual distance: ${abstractionRules[s.abstraction]}.\nTranslate cultural meaning into motif, repetition, ground, connections and voids. Do not write the story, draw a map, copy a logo or claim an official cultural emblem.`}
function syncStory(){const enabled=$('#storyEnabled').checked;$('#storyFields').hidden=!enabled;const matched=storyMatchesImage();$('#storyState').textContent=matched?'This image was generated from the story above. The design plan was used in its image prompt.':'The image above was made before this story, or from different story text. Generate a new one to apply the current version.';if(enabled&&!matched)$('#resultNote').textContent='Current image does not reflect this story yet. Generate a new study below.';else if(matched)$('#resultNote').textContent='Story translation completed. Inspect the design plan below and compare it with the image.';renderTranslation(matched?generatedTranslation:null);syncRecipe()}
$('#storyEnabled').onchange=syncStory;
$$('#storyFields input,#storyFields textarea,#storyFields select').forEach(el=>el.oninput=syncStory);
$('#storyExample').onclick=()=>{$('#storyEnabled').checked=true;$('#storyContext').value='Cambridge, Massachusetts / MIT';$('#storyNarrative').value='An imagined walk from the Charles River into a campus where paths meet, ideas travel, and making happens across disciplines.';$('#storySymbols').value='river current, bridge spans, intersecting paths';$('#storyFocus').value='routes';$('#storyAbstraction').value='balanced';syncStory();$('#storyFields').scrollIntoView({behavior:'smooth',block:'nearest'})};
function motifSvg(key){const m=motifs[key];return `<svg viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><g>${m.icon}</g></svg>`}
function setupChoices(){
 $('#motifChoices').innerHTML=Object.entries(motifs).map(([k,m])=>`<button type="button" data-motif="${k}" aria-pressed="${k===settings.motif}">${motifSvg(k)}<span>${m.label}</span></button>`).join('');
 $$('#motifChoices button').forEach(b=>b.onclick=()=>{settings.motif=b.dataset.motif;sync();});
 $$('#surfaceChoices button').forEach(b=>b.onclick=()=>{settings.surface=b.dataset.surface;$$('#surfaceChoices button').forEach(x=>x.setAttribute('aria-pressed',x===b));syncRecipe();});
}
function sync(){for(const [k,v] of Object.entries(settings)){const el=document.querySelector(`[name="${k}"]`);if(el)el.value=v}$('#densityValue').textContent=settings.density+'%';$('#weightValue').textContent=settings.weight+' / 5';$$('#motifChoices button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.motif===settings.motif));syncRecipe();drawSketch();}
function recipe(){const m=motifs[settings.motif].label.toLowerCase();const surface={ink:'black material with white open voids',thread:'warm ivory thread on a cool white ground',cutwork:'paper-cut surface with clean shadowless edges'}[settings.surface];return `Create one square, flat lace pattern study for material research.\nMotif: ${m}.\nArrangement: ${settings.repeat.replace('halfdrop','half-drop rows').replace('grid','square translation grid').replace('mirror','bilateral mirror repeat').replace('radial','radial medallion').replace('organic','flowing organic field')}.\nGround: ${settings.ground.replace('diamond','diamond mesh').replace('hexagonal','hexagonal net').replace('bridges','open connecting bridges').replace('none','no ground; separated motifs')}.\nOpen space: ${settings.density} percent. Thread weight: ${settings.weight} of 5. Detail: ${settings.detail}. Edge: ${settings.edge}. Surface: ${surface}.\nOrthographic, edge-to-edge, no perspective, shadows, garments, boats, lettering or watermark. Keep the pattern visually connected and show two scales: a legible motif and a smaller ground. This is an exploratory specimen, not a certified seamless repeat or engineering drawing.${storyRecipe()}`}
function syncRecipe(){const sameSettings=generatedSettings&&JSON.stringify(settings)===JSON.stringify(generatedSettings);$('#promptPreview').textContent=generatedPrompt&&sameSettings&&storyMatchesImage()?generatedPrompt:recipe()}
function drawSketch(){const ground=settings.ground==='diamond'?'M0 0L40 40M40 0L0 40':'M20 0V40M0 20H40';$('#sketch').innerHTML=`<svg viewBox="0 0 240 240" xmlns="http://www.w3.org/2000/svg"><defs><pattern id="g" width="40" height="40" patternUnits="userSpaceOnUse"><g stroke="#617c89" stroke-width=".7" opacity=".4"><path d="${ground}"/></g></pattern></defs><rect width="240" height="240" fill="#f3f7f8"/><rect width="240" height="240" fill="url(#g)"/><g transform="translate(120 120) scale(1.5)" fill="none" stroke="#253943" stroke-width="1.4">${motifs[settings.motif].icon}</g></svg>`}
function showPage(id){$$('.page').forEach(p=>{p.hidden=p.id!==id;p.classList.toggle('active',p.id===id)});$$('[data-page]').forEach(b=>b.setAttribute('aria-current',b.dataset.page===id?'page':'false'));location.hash=id}
$$('[data-page]').forEach(b=>b.onclick=()=>showPage(b.dataset.page));
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
function setLoading(on){$('#generationOverlay').hidden=!on;$('#generate').disabled=on}
async function checkConnection(){try{const r=await fetch(`${apiOrigin}/api/health`);const d=await r.json();$('#apiStatus').textContent=d.configured?'OpenAI image connection ready':'API key needed on server';$('#apiStatus').classList.toggle('ready',!!d.configured);return d.configured}catch{$('#apiStatus').textContent='Image service unavailable';$('#apiStatus').classList.remove('ready');return false}}
async function generate(e){e.preventDefault();$('#generationError').hidden=true;const story=getStory();if(story.enabled&&(!story.context||!story.narrative)){$('#generationError').hidden=false;$('#generationError').textContent='Add a place or community and a short story before generating.';(!story.context?$('#storyContext'):$('#storyNarrative')).focus();return}setLoading(true);$('#generationOverlay p').textContent=story.enabled?'Translating your story into a design plan, then generating lace.':'A new image is being generated.';const started=Date.now();try{const r=await fetch(`${apiOrigin}/api/generate`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({settings,story})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Generation failed');currentImage=`data:image/png;base64,${d.image}`;$('#resultImage').src=currentImage;$('#resultImage').alt=story.enabled?`Generated lace study translating ${story.context}`:'Generated lace pattern study';$('#specimenLabel').textContent=(story.enabled?'STORY STUDY':'GENERATED')+' / '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});$('#imageCaption').textContent=`OpenAI image study · ${d.model}${story.enabled?' · '+story.context:''} · ${((Date.now()-started)/1000).toFixed(1)}s`;$('#resultNote').textContent=story.enabled?'Story translation completed. Inspect the design plan below and compare it with the image.':'This is a visual hypothesis. Pin it, download it, or test it in Image study.';generatedStory=story.enabled?{...story}:null;generatedTranslation=d.translation||null;generatedSettings={...settings};generatedPrompt=d.prompt||null;syncStory();toast('New pattern generated');checkConnection()}catch(err){$('#generationError').hidden=false;$('#generationError').textContent=err.message.includes('API key')?'Add OPENAI_API_KEY to the server environment, then restart.':err.message;toast('Generation could not complete')}finally{setLoading(false)}}
$('#patternForm').onsubmit=generate;
$('#generateStory').onclick=()=>$('#patternForm').requestSubmit();
$$('#patternForm select,#patternForm input[type=range]').forEach(el=>el.oninput=()=>{settings[el.name]=el.type==='range'?Number(el.value):el.value;sync()});
$('#reset').onclick=()=>{settings={motif:'rosette',repeat:'halfdrop',ground:'diamond',density:55,weight:3,detail:'balanced',edge:'repeat',surface:'ink',quality:'medium'};$('#storyEnabled').checked=false;$('#storyContext').value='';$('#storyNarrative').value='';$('#storySymbols').value='';$('#storyFocus').value='routes';$('#storyAbstraction').value='balanced';syncStory();sync()};
$('#outputView').onclick=()=>{$('#resultImage').hidden=false;$('#sketch').hidden=true;$('#outputView').setAttribute('aria-pressed','true');$('#sketchView').setAttribute('aria-pressed','false')};$('#sketchView').onclick=()=>{$('#resultImage').hidden=true;$('#sketch').hidden=false;$('#outputView').setAttribute('aria-pressed','false');$('#sketchView').setAttribute('aria-pressed','true');drawSketch()};
$('#downloadImage').onclick=()=>{const a=document.createElement('a');a.href=currentImage;a.download='lace-lab-pattern.png';a.click()};$('#fullImage').onclick=()=>{$('#enlargedImage').src=currentImage;$('#imageDialog').showModal()};
$('#pin').onclick=()=>{history.push({src:currentImage,settings:{...settings},story:getStory()});$('#history').hidden=false;$('#historyItems').innerHTML=history.map((h,i)=>`<button class="history-item" data-i="${i}"><img src="${h.src}" alt="Pinned study ${i+1}"><span>${motifs[h.settings.motif].label}<br>${h.story?.enabled?'Story translation':h.settings.repeat}</span></button>`).join('');$$('.history-item').forEach(b=>b.onclick=()=>{$('#resultImage').src=history[b.dataset.i].src;currentImage=history[b.dataset.i].src});toast('Study pinned')};
$('#copyPrompt').onclick=async()=>{await navigator.clipboard?.writeText(recipe());toast('Recipe copied')};$('#exportRecipe').onclick=()=>{const blob=new Blob([JSON.stringify({version:3,createdAt:new Date().toISOString(),settings,story:getStory(),recipe:recipe(),pinned:history.map(x=>({settings:x.settings,story:x.story}))},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='lace-lab-study.json';a.click()};$('#checkConnection').onclick=checkConnection;
$('#studyResult').onclick=()=>showPage('analysis');
const cases=[
 {id:'01',title:'Lace Square',meta:'Italy · 1500s–1600s · reticella needle lace',image:'https://openaccess-cdn.clevelandart.org/1920.1098/1920.1098_web.jpg',url:'https://www.clevelandart.org/art/1920.1098',tags:['geometric','star + ring','square repeat'],obs:'A central eight-pointed star sits inside a circular ring; a knotted grid connects it to a square border.',q:'When cells join, does the corner become a new motif?',family:'diamond'},
 {id:'02',title:'Pointed edging',meta:'Genoa · 17th century · bobbin lace',image:'https://openaccess-cdn.clevelandart.org/1920.985/1920.985_web.jpg',url:'https://www.clevelandart.org/art/1920.985',tags:['ground','wheel repeat','pointed edge'],obs:'Wheels and pointed pendants create two rhythms. The edge is not simply a crop of the interior.',q:'How can a one-direction repeat keep its border continuous?',family:'diamond'},
 {id:'03',title:'Floral mesh',meta:'Flanders · 17th–18th century · bobbin lace',image:'https://openaccess-cdn.clevelandart.org/1923.1040/1923.1040_web.jpg',url:'https://www.clevelandart.org/art/1923.1040',tags:['botanical','mesh','bilateral'],obs:'Scrolling foliage sits against fine mesh. Compare bilateral balance with local variation.',q:'Does the ground connect the flowers, or do the branches become the ground?',family:'botanical'},
 {id:'04',title:'Mixed construction',meta:'Italy · 17th century · needle and bobbin lace',image:'https://openaccess-cdn.clevelandart.org/1920.1237/1920.1237_web.jpg',url:'https://www.clevelandart.org/art/1920.1237',tags:['geometric','S-connectors','islands'],obs:'Circles, flowers and curved connectors form one field. Separate solid motifs from bridges.',q:'How many islands remain if the connectors are removed?',family:'rosette'},
 {id:'05',title:'Floral needle lace',meta:'Alençon, France · 1840–1860 · needle lace',image:'https://openaccess-cdn.clevelandart.org/1930.652/1930.652_web.jpg',url:'https://www.clevelandart.org/art/1930.652',tags:['botanical','swag','scalloped edge'],obs:'Swags, branches, mesh and edge work at different scales. Keep those scales distinct.',q:'What must simplify when thread-scale lace becomes a cut panel?',family:'botanical'},
 {id:'06',title:'Maltese collar',meta:'Malta · third quarter 19th century · silk',image:'https://collectionapi.metmuseum.org/api/collection/v1/iiif/158824/332483/main-image',url:'https://www.metmuseum.org/art/collection/search/158824',tags:['ground','Maltese cross','leaf + tulip'],obs:'A leaf and tulip vocabulary is held by a Maltese-cross ground. The ground is part of the identity, not empty filler.',q:'Can the cross ground be varied while keeping the local grammar?',family:'botanical'},
 {id:'07',title:'Amoy Lace Guild sample',meta:'Xiamen, China · 1905–1912 · linen Torchon insertion',image:'https://ids.si.edu/ids/deliveryService?id=NMAH-AHB2013q001588',url:'https://www.si.edu/object/amoy-lace-guild-bobbin-lace-sample:nmah_624030',tags:['geometric','roseground','half-stitch trail'],obs:'Diamond motifs, roseground and half-stitch trails show how a small band can carry several densities.',q:'Which density changes first when the band becomes a surface?',family:'diamond'},
 {id:'08',title:'Cutwork & bobbin border',meta:'Italy · late 16th–early 17th century · linen cutwork, embroidery, bobbin lace',image:'https://collectionapi.metmuseum.org/api/collection/v1/iiif/218870/441321/main-image',url:'https://www.metmuseum.org/art/collection/search/218870',tags:['geometric','ground','edge'],obs:'Openings are removed from a linen foundation and embroidered; bobbin lace finishes the border. Compare the cut interior with the thread-built edge.',q:'Which bridges must remain if an opening is cut from a larger sheet?',family:'diamond',process:'removed',method:'Cutwork + embroidery'},
 {id:'09',title:'Drawnwork',meta:'Sicily, Italy · 16th–17th century · drawnwork',image:'https://collectionapi.metmuseum.org/api/collection/v1/iiif/217244/440158/main-image',url:'https://www.metmuseum.org/art/collection/search/217244',tags:['geometric','ground','grid'],obs:'The woven foundation is edited by removing selected threads. The surviving warp and weft provide a ready-made scaffold for new openings.',q:'Could a retained grid guide a subtractive pattern on a larger surface?',family:'diamond',process:'removed',method:'Drawn-thread work'},
 {id:'10',title:'Irish crochet border',meta:'Ireland · 19th century · crochet',image:'https://collectionapi.metmuseum.org/api/collection/v1/iiif/214772/439021/main-image',url:'https://www.metmuseum.org/art/collection/search/214772',tags:['botanical','edge','loops'],obs:'Crochet builds the border stitch by stitch rather than removing a woven ground. Follow where loops grow, join and change density.',q:'Can separate raised motifs still read as one connected edge?',family:'botanical',process:'thread',method:'Crochet lace'},
 {id:'11',title:'Tatted edging',meta:'Germany · 19th century · tatting',image:'https://collectionapi.metmuseum.org/api/collection/v1/iiif/215815/439662/main-image',url:'https://www.metmuseum.org/art/collection/search/215815',tags:['geometric','edge','rings'],obs:'Tatting constructs lace from knots, rings and chains. Small joins can carry a repeated edge without a continuous fabric base.',q:'What changes if the joints become visible connection points at boat scale?',family:'rosette',process:'thread',method:'Tatting / knotting'},
 {id:'12',title:'Machine-made fragment',meta:'Germany · 19th century · machine-made lace',image:'https://collectionapi.metmuseum.org/api/collection/v1/iiif/216757/440139/main-image',url:'https://www.metmuseum.org/art/collection/search/216757',tags:['ground','repeat','mechanical'],obs:'A machine-made specimen brings regularity and reproducible repeat into the comparison. Look for the difference between a local motif and the field that carries it.',q:'Which variation is lost when every unit is mechanically repeated?',family:'scroll',process:'machine',method:'Machine-made lace'},
 {id:'13',title:'Alençon cap crown',meta:'France · 1720–1740 · needle lace',image:'https://collectionapi.metmuseum.org/api/collection/v1/iiif/229617/488406/main-image',url:'https://www.metmuseum.org/art/collection/search/229617',tags:['botanical','ground','hexagon'],obs:'The museum describes a ground of solid hexagons within hexagonal outlines, with palm-like foliage above it. Ground geometry and motif operate at different scales.',q:'How might a hexagonal ground bend across a curved hull?',family:'botanical',process:'thread',method:'Needle lace'},
 {id:'14',title:'Reticella sampler',meta:'Britain · Margret Barber · 1661–1663 · linen embroidery and reticella',image:'https://collectionapi.metmuseum.org/api/collection/v1/iiif/228294/470483/main-image',url:'https://www.metmuseum.org/art/collection/search/228294',tags:['geometric','grid','bands'],obs:'The lower band uses reticella: threads are withdrawn from a woven foundation and the open grid is stabilized with stitches. The sampler records several techniques side by side.',q:'Can one surface shift between filled, drawn and open zones?',family:'diamond',process:'removed',method:'Reticella / drawn-thread work'}
];
const originalMethods={'01':'Reticella needle lace','02':'Bobbin lace','03':'Bobbin lace','04':'Needle + bobbin lace','05':'Needle lace','06':'Maltese lace','07':'Torchon bobbin lace'};
const caseMethod=c=>c.method||originalMethods[c.id];
$('#atlasFilters').insertAdjacentHTML('beforeend','<button data-filter="thread" aria-pressed="false">Thread-built</button><button data-filter="removed" aria-pressed="false">Cut &amp; drawn</button><button data-filter="machine" aria-pressed="false">Machine-made</button>');
