function renderAtlas(filter='all'){const data=cases.filter(c=>filter==='all'||c.tags.includes(filter)||(c.process||'thread')===filter);$('#caseCount').textContent=String(data.length).padStart(2,'0')+' specimens';$('#references').innerHTML=data.map(c=>`<article class="reference-card" data-tags="${c.tags.join(' ')}"><div class="image-wrap" data-id="${c.id}"><img src="${c.image}" alt="${c.title}, ${c.meta}" loading="lazy" onerror="this.outerHTML='<p class=\'image-error\'>Image unavailable<br>Open the collection record below ↗</p>'"><span class="image-index">CASE / ${c.id}</span></div><div class="body"><p class="case-method">${caseMethod(c)}</p><p class="eyebrow">${c.meta}</p><h2>${c.title}</h2><div class="pattern-tags">${c.tags.map(t=>`<span>${t}</span>`).join('')}</div><p>${c.obs}</p><div class="case-actions"><button data-use="${c.id}">Use this grammar ↗</button><button data-open="${c.id}">Read case ↗</button></div></div></article>`).join('');$$('[data-open]').forEach(b=>b.onclick=()=>openCase(b.dataset.open));$$('[data-use]').forEach(b=>b.onclick=()=>{const c=cases.find(x=>x.id===b.dataset.use);settings.motif=c.family;sync();showPage('studio');toast('Grammar loaded as a starting point')});$$('.image-wrap').forEach(x=>x.onclick=()=>openCase(x.dataset.id))}
function openCase(id){const c=cases.find(x=>x.id===id);$('#caseDetail').innerHTML=`<div class="detail-image"><img src="${c.image}" alt="${c.title}"></div><div><p class="eyebrow">CASE / ${c.id} · ${caseMethod(c).toUpperCase()}</p><h2>${c.title}</h2><p>${c.meta}</p><div class="pattern-tags">${c.tags.map(t=>`<span>${t}</span>`).join('')}</div><p><b>Observed structure</b><br>${c.obs}</p><p><b>Research question</b><br>${c.q}</p><a class="source-link" href="${c.url}" target="_blank" rel="noopener">Open collection record ↗</a><p class="micro-copy">Use the source page for rights and object context. This reading is a working abstraction for Lace Lab.</p></div>`;$('#caseDialog').showModal()}
